/**
 * Where the call signatures actually live. This file deliberately shares no
 * vocabulary with a question about the router, so a query naming the verb and
 * its arguments cannot rank it.
 */
export interface HandlerInterface<E, M extends string, B extends string> {
    <P extends string>(route: P, fn: (ctx: unknown) => Response): Bound<E, B>;
    <P extends string>(route: P, ...rest: Array<(ctx: unknown) => Response>): Bound<E, B>;
}

export interface JSONRespond {
    <T>(object: T, status?: number, extra?: Record<string, string>): Response;
}

export interface Bound<E, B extends string> {
    readonly marker: unique symbol;
}
